// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.stream.Stream;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class LmdbTestTemporaryDirectoryTest {

	@Test
	void javaTemporaryFilesStayWithinTheTestForkDirectory(@TempDir Path junitDirectory) throws Exception {
		Path forkTemporaryDirectory = Path.of(System.getProperty("java.io.tmpdir")).toRealPath();
		String count = System.getProperty("rdf4j.lmdb.test.forkCount", "1");
		if (LmdbTestForkDirectories.effectiveForkCount(count, Runtime.getRuntime().availableProcessors()) > 0) {
			Path testTemporaryRoot = Path.of(System.getProperty("rdf4j.test.tmpDirectory"))
					.toAbsolutePath()
					.normalize();
			if (Files.exists(testTemporaryRoot)) {
				testTemporaryRoot = testTemporaryRoot.toRealPath();
			}
			assertThat(forkTemporaryDirectory).isDirectory().isNotEqualTo(testTemporaryRoot);
			assertThat(forkTemporaryDirectory.startsWith(testTemporaryRoot))
					.as("the JVM temporary directory %s must belong to %s", forkTemporaryDirectory, testTemporaryRoot)
					.isTrue();
			assertThat(forkTemporaryDirectory.getFileName().toString())
					.isEqualTo("fork-" + System.getProperty("rdf4j.lmdb.test.forkNumber"));
		}
		assertThat(junitDirectory.toRealPath()).startsWith(forkTemporaryDirectory);

		Path nioFile = Files.createTempFile("lmdb-test-nio-", ".tmp");
		File ioFile = File.createTempFile("lmdb-test-io-", ".tmp");
		try {
			assertThat(nioFile.toRealPath().getParent()).isEqualTo(forkTemporaryDirectory);
			assertThat(ioFile.toPath().toRealPath().getParent()).isEqualTo(forkTemporaryDirectory);
		} finally {
			Files.deleteIfExists(nioFile);
			Files.deleteIfExists(ioFile.toPath());
		}
	}

	@ParameterizedTest
	@CsvSource({ "4,8,1,4", "4,8,3,12", "0.5C,8,3,12", "1.5C,8,2,24", "0.01C,8,2,2", "0C,8,1,0",
			"0,8,1,0" })
	void preparesDirectoriesForSurefireAndReactorConcurrency(String count, int processors, int projects,
			int expected, @TempDir Path root) throws Exception {
		LmdbTestForkDirectories.prepare(root, count, processors, projects);
		try (Stream<Path> directories = Files.list(root)) {
			assertThat(directories).hasSize(expected);
		}
		for (int fork = 1; fork <= expected; fork++) {
			assertThat(root.resolve("fork-" + fork)).isDirectory();
		}
	}

	@Test
	void resolvesRelativeAndAbsoluteTemporaryRoots(@TempDir Path projectDirectory) {
		Path relative = Path.of("target", "test-temp");
		Path absolute = projectDirectory.resolve("elsewhere").toAbsolutePath();
		assertThat(LmdbTestForkDirectories.resolveTemporaryRoot(projectDirectory, relative))
				.isEqualTo(projectDirectory.resolve(relative).toAbsolutePath().normalize());
		assertThat(LmdbTestForkDirectories.resolveTemporaryRoot(projectDirectory, absolute)).isEqualTo(absolute);
	}
}
